<?php
$nightMethods=['EGYPTIAN'=>['المصرية','Egyptian'],'MUSLIM_WORLD_LEAGUE'=>['رابطة العالم الإسلامي','Muslim World League'],'UMM_AL_QURA'=>['أم القرى','Umm Al-Qura'],'KARACHI'=>['كراتشي','Karachi'],'DUBAI'=>['دبي','Dubai'],'MOON_SIGHTING_COMMITTEE'=>['لجنة رؤية الهلال','Moon Sighting Committee']];
$nightRules=['MIDDLE_OF_THE_NIGHT'=>['منتصف الليل','Middle of night'],'SEVENTH_OF_THE_NIGHT'=>['سبع الليل','Seventh of night'],'TWILIGHT_ANGLE'=>['زاوية الشفق','Twilight angle']];
$nightDraft=$nightPrayerPublicDefaults;$nightDraftConflict=false;
if ($nightDraft !== null && $adminError !== '' && ($_POST['kind'] ?? '') === 'night-prayer-defaults') {
    foreach (['calculation_method','madhab','high_latitude_rule','target_verses','source_name_ar','source_name_en','source_url','intro_ar','intro_en'] as $field) if(is_string($_POST[$field]??null))$nightDraft[$field]=mb_substr($_POST[$field],0,1201,'UTF-8');
    $nightDraft['enabled']=isset($_POST['enabled']) ? '1' : '0';
    $revision=filter_var($_POST['expected_revision']??null,FILTER_VALIDATE_INT);$nightDraftConflict=$revision !== (int)$nightPrayerPublicDefaults['revision'];$nightDraft['revision']=(string)($revision===false ? 0 : $revision);
}
?>
<section class="admin-inventory admin-panel" id="admin-night-prayer" data-admin-panel hidden>
<div class="section-heading"><h2><?= $serviceCopy('الإعدادات العامة لقيام الليل','Public Night Prayer defaults') ?></h2><span class="source-chip"><?= $nightPrayerPublicDefaults === null ? $serviceCopy('غير متاح','Unavailable') : $serviceCopy('النسخة المحفوظة','Saved version').' '.(int)$nightPrayerPublicDefaults['revision'] ?></span></div>
<p class="source-note"><?= $serviceCopy('تُنشر هذه القيم عبر الواجهة العامة للتطبيقات المتوافقة. الاختيارات الشخصية تبقى بيد المستخدم. هذه الشاشة لا تعرض جلسات العبادة أو الملاحظات أو الإعفاءات الخاصة.','These values are published through the API for compatible clients. Personal choices remain under user control. This panel does not expose private worship sessions, notes or exemptions.') ?></p>
<?php if ($nightDraft === null): ?><p class="notice notice-error"><?= $serviceCopy('تعذرت قراءة الإعدادات العامة. احتُفظ بالقيم الحالية. أعد المحاولة قبل التعديل.','Public defaults could not be read. Current values are preserved; retry before editing.') ?></p><?php else: ?>
<?php if ($nightDraftConflict): ?><p class="notice notice-error" data-night-defaults-conflict><?= $serviceCopy('احتُفظ بمسودتك دون الكتابة فوق النسخة الأحدث.','Your draft is retained; the newer version has not been overwritten.') ?> <a href="/admin?defaults_reload=1#admin-night-prayer"><?= $serviceCopy('تحميل النسخة الحالية','Load current version') ?></a></p><?php endif; ?>
<form class="form-stack" method="post" action="/admin#admin-night-prayer" data-night-defaults-form><?= csrf_field() ?><input type="hidden" name="kind" value="night-prayer-defaults"><input type="hidden" name="expected_revision" value="<?= e($nightDraft['revision']) ?>">
<label class="check-label"><input type="checkbox" name="enabled" <?= $nightDraft['enabled']==='1' ? 'checked' : '' ?>><?= $serviceCopy('تفعيل الاقتراحات العامة','Enable public suggestions') ?></label>
<div class="admin-form-grid"><?php foreach (['calculation_method'=>['طريقة الحساب','Calculation method',$nightMethods],'madhab'=>['المذهب في حساب العصر','Asr calculation madhab',['standard'=>['قياسي (شافعي)','Standard (Shafi)'],'hanafi'=>['حنفي','Hanafi']]],'high_latitude_rule'=>['قاعدة خطوط العرض العليا','High latitude rule',$nightRules]] as $field=>$definition): ?><label><?= $serviceCopy($definition[0],$definition[1]) ?><select name="<?= $field ?>" required><?php if(!isset($definition[2][$nightDraft[$field]])): ?><option value="<?= e($nightDraft[$field]) ?>" selected disabled><?= $serviceCopy('قيمة غير متاحة — اختر قيمة صالحة','Unavailable value — choose a valid option') ?></option><?php endif; ?><?php foreach($definition[2] as $code=>$label): ?><option value="<?= $code ?>" <?= $nightDraft[$field]===$code ? 'selected' : '' ?>><?= $serviceCopy(...$label) ?></option><?php endforeach; ?></select></label><?php endforeach; ?>
<label><?= $serviceCopy('هدف الآيات المقترح','Suggested verse target') ?><input type="number" name="target_verses" dir="ltr" min="1" max="6236" value="<?= e($nightDraft['target_verses']) ?>" required></label></div>
<?php foreach (['ar'=>['اسم المصدر بالعربية','Arabic source name'],'en'=>['اسم المصدر بالإنجليزية','English source name']] as $language=>$label): ?><label><?= $serviceCopy(...$label) ?><input name="source_name_<?= $language ?>" dir="<?= $language==='ar' ? 'rtl' : 'ltr' ?>" minlength="2" maxlength="120" value="<?= e($nightDraft['source_name_'.$language]) ?>" required></label><?php endforeach; ?>
<label><?= $serviceCopy('رابط توثيق المصدر','Source attribution link') ?><input type="url" name="source_url" dir="ltr" maxlength="500" value="<?= e($nightDraft['source_url']) ?>" required></label>
<?php foreach (['ar'=>['النص التعريفي بالعربية','Arabic introduction'],'en'=>['النص التعريفي بالإنجليزية','English introduction']] as $language=>$label): ?><label><?= $serviceCopy(...$label) ?><textarea name="intro_<?= $language ?>" dir="<?= $language==='ar' ? 'rtl' : 'ltr' ?>" maxlength="1200" rows="3"><?= e($nightDraft['intro_'.$language]) ?></textarea></label><?php endforeach; ?>
<button class="button button-primary" <?= $nightDraftConflict ? 'disabled' : '' ?>><?= $serviceCopy('حفظ الإعدادات العامة','Save public defaults') ?></button></form><?php endif; ?></section>
